py_sources.utils/takeoff/ski_jump_geometry.py:
"""滑跃甲板圆弧几何：入口切线水平，出口切线角 = 资料给定滑跃角。

仅需出口切线角（°）；可选跳台唇口高度 h（m）确定圆弧半径 R = h / (1 − cos α)。
未给高度时用参考半径 SKI_JUMP_REF_RADIUS_M，弧长/水平投影/高度均由 R 与 α 导出。
"""
from __future__ import annotations

import math
from dataclasses import dataclass

from utils.takeoff.takeoff_config import physics_config

# 仅给定滑跃角、无唇口高度时的参考圆弧半径，m（典型 STOBAR 量级）
SKI_JUMP_REF_RADIUS_M = float(physics_config()['ski_jump_ref_radius_m'])


@dataclass(frozen=True)
class SkiJumpArc:
    angle_deg: float
    angle_rad: float
    radius_m: float
    arc_length_m: float
    horizontal_m: float
    lip_height_m: float

    @property
    def cos_exit(self) -> float:
        return math.cos(self.angle_rad)

    @property
    def sin_exit(self) -> float:
        return math.sin(self.angle_rad)


def compute_ski_jump_arc(angle_deg: float, lip_height_m: float | None = None,
                         radius_m: float | None = None) -> SkiJumpArc:
    """
    计算圆弧滑跃段几何。

    优先级：显式 radius_m > lip_height_m > 参考半径。
    """
    if angle_deg <= 0:
        raise ValueError('滑跃角必须为正')
    angle_rad = math.radians(angle_deg)
    if radius_m is not None and radius_m > 0:
        r = radius_m
        h = r * (1.0 - math.cos(angle_rad))
    elif lip_height_m is not None and lip_height_m > 0:
        h = lip_height_m
        r = h / (1.0 - math.cos(angle_rad))
    else:
        r = SKI_JUMP_REF_RADIUS_M
        h = r * (1.0 - math.cos(angle_rad))
    arc_length = r * angle_rad
    horizontal = r * math.sin(angle_rad)
    return SkiJumpArc(
        angle_deg=angle_deg,
        angle_rad=angle_rad,
        radius_m=r,
        arc_length_m=arc_length,
        horizontal_m=horizontal,
        lip_height_m=h,
    )


def deck_angle_rad_at_s(s_m: float, arc: SkiJumpArc) -> float:
    """沿弧长 s 处甲板切线与水平面夹角（rad），0 → 出口角。"""
    if s_m <= 0:
        return 0.0
    return min(s_m / arc.radius_m, arc.angle_rad)


def deck_angle_deg_at_s(s_m: float, arc: SkiJumpArc) -> float:
    return math.degrees(deck_angle_rad_at_s(s_m, arc))


def deck_cos_sin_at_s(s_m: float, arc: SkiJumpArc) -> tuple[float, float]:
    phi = deck_angle_rad_at_s(s_m, arc)
    return math.cos(phi), math.sin(phi)


def horizontal_at_s(s_m: float, arc: SkiJumpArc) -> float:
    """自滑跃入口起累计水平距离，m。"""
    phi = deck_angle_rad_at_s(s_m, arc)
    return arc.radius_m * math.sin(phi)


def deck_height_at_s(s_m: float, arc: SkiJumpArc) -> float:
    """沿弧长 s 处甲板表面相对平甲板的高度，m。"""
    phi = deck_angle_rad_at_s(s_m, arc)
    return arc.radius_m * (1.0 - math.cos(phi))

py_sources.utils/takeoff/search_utils.py:
"""Shared coarse/fine parameter search grids.

粗搜：模块级 ``range(start, stop + 1, step)``。
精搜：在粗搜最优值附近，对该变量 ± 粗搜步长；精搜步长默认为 1。
甲板/平直段长度精搜：仅向更短方向搜索 ``[best - coarse_step, best)``，因更长甲板不会更优。
"""


def grid_step(grid) -> int:
    """Return step size of a coarse ``range`` or sorted sequence."""
    if isinstance(grid, range):
        return grid.step or 1
    vals = list(grid)
    if len(vals) < 2:
        return 1
    return vals[1] - vals[0]


def fine_range_symmetric(best, coarse_step, fine_step=1, min_val=None, max_val=None):
    """Fine search grid: best ± coarse_step (inclusive endpoints)."""
    lo = int(best) - coarse_step
    hi = int(best) + coarse_step
    if min_val is not None:
        lo = max(lo, min_val)
    if max_val is not None:
        hi = min(hi, max_val)
    return range(lo, hi + 1, fine_step)


def fine_range_deck(best, coarse_step, fine_step=1, min_val=0):
    """Fine search for deck/runway length: only lengths shorter than *best*."""
    lo = max(int(best) - coarse_step, min_val)
    hi = int(best)
    if lo >= hi:
        return range(0)
    return range(lo, hi, fine_step)

py_sources.utils/specs.py:
"""舰载机 / 航母参数规格。"""
from __future__ import annotations

from dataclasses import dataclass

from utils.takeoff.ski_jump_geometry import compute_ski_jump_arc
from utils.takeoff.takeoff_config import physics_config

_PHYS = physics_config()
PILOT_LOAD_KG = float(_PHYS['pilot_load_kg'])
A2A_MISSILE_COUNT = int(_PHYS['a2a_missile_count'])

# 数据库 type_label：垂直/短距起降（VTOL/STOVL）与倾转旋翼
VTOL_TYPE_LABEL = 'v/stol'
TILTROTOR_TYPE_LABEL = 'tiltrotor'
CONVENTIONAL_TYPE_LABEL = 'conventional'

# 需要主喷管尾流波及模型的 Web/仿真模式（须配合 VTOL 机型）
PLUME_SIMULATION_MODES = frozenset({'short_takeoff', 'short_ski_jump'})


def is_vtol_aircraft(aircraft: AircraftSpec | str) -> bool:
    """是否为 VTOL/STOVL 机型（type_label == 'v/stol'）。"""
    label = aircraft if isinstance(aircraft, str) else aircraft.type_label
    return label == VTOL_TYPE_LABEL


def is_tiltrotor_aircraft(aircraft: AircraftSpec | str) -> bool:
    """是否为倾转旋翼机型（type_label == 'tiltrotor'）。"""
    label = aircraft if isinstance(aircraft, str) else aircraft.type_label
    return label == TILTROTOR_TYPE_LABEL


def is_conventional_aircraft(aircraft: AircraftSpec | str) -> bool:
    """是否为常规固定翼舰载机。"""
    label = aircraft if isinstance(aircraft, str) else aircraft.type_label
    return label == CONVENTIONAL_TYPE_LABEL


def simulation_uses_plume_model(mode: str, aircraft: AircraftSpec) -> bool:
    """当前仿真是否应计算主喷管尾流波及范围（仅 VTOL + 短距模式）。"""
    return mode in PLUME_SIMULATION_MODES and is_vtol_aircraft(aircraft)


def uses_propeller_power(aircraft: AircraftSpec) -> bool:
    """是否按恒定轴功率（桨盘动量理论）计算起飞推力，而非恒定喷气推力。"""
    return bool(
        aircraft.shaft_power_sl_w and aircraft.shaft_power_sl_w > 0
        and aircraft.prop_diameter_m and aircraft.prop_diameter_m > 0
    )


@dataclass(frozen=True)
class AircraftSpec:
    id: str
    name: str
    type_label: str  # 'conventional' | 'v/stol' | 'tiltrotor'
    sweep_le_deg: float
    wingspan_m: float
    wing_area_m2: float
    wing_height_m: float
    aircraft_role: str = 'fighter'  # 'fighter' | 'bomber'
    wing_body_blend: bool = False
    mtow_kg: float = 0.0
    empty_kg: float = 0.0
    internal_fuel_kg: float = 0.0
    max_payload_kg: float = 0.0  # 最大外挂/载弹量（资料值，非 MTOW 推算）
    bvr_missile: str = ''
    missile_mass_kg: float = 0.0
    cd0: float = 0.039
    t_max_sl_n: float | None = None
    t_main_stovl_sl_n: float | None = None
    t_liftfan_sl_n: float | None = None
    t_rollposts_sl_n: float | None = None
    exhaust_mdot_kg_s: float | None = None
    exhaust_d0_m: float | None = None
    exhaust_height_m: float | None = None
    # 倾转旋翼 / 涡桨：海平面总轴功率与桨盘直径（推力由功率换算）
    shaft_power_sl_w: float | None = None
    prop_diameter_m: float | None = None
    nacelle_blockage_frac: float | None = None
    n_pilots: int = 1
    notes: str = ''
    # 起飞增升：仅 layout=canard 且填了鸭翼面积时启用
    layout: str = 'conventional'
    canard_htail_area_m2: float | None = None

    @property
    def is_vtol(self) -> bool:
        """VTOL/STOVL 机型（如 F-35B、AV-8B）。"""
        return is_vtol_aircraft(self)

    @property
    def is_tiltrotor(self) -> bool:
        """倾转旋翼机型（如 MV-22）。"""
        return is_tiltrotor_aircraft(self)

    @property
    def uses_propeller_power(self) -> bool:
        """涡桨 / 倾转旋翼：有轴功率与桨盘直径，滑跃按恒定功率而非恒定推力。"""
        return uses_propeller_power(self)

    @property
    def has_lift_fan(self) -> bool:
        """是否配备升力风扇（F-35B 有，鹞式/AV-8B 无）。"""
        return bool(self.t_liftfan_sl_n and self.t_liftfan_sl_n > 0)

    def exhaust_plume_params(self):
        """构造本机尾流模型参数；未填 ṁ/d₀ 时用机型默认值或 Pegasus/F-35B 回退。"""
        from utils.takeoff.exhaust_plume import (
            EXHAUST_D0_M,
            EXHAUST_HEIGHT_M,
            EXHAUST_MDOT_KG_S,
            ExhaustPlumeParams,
            PEGASUS_AIRFLOW_LB_S,
            calc_exhaust_d0_from_engine_diameter,
            calc_exhaust_u0_from_thrust_mdot,
            lb_s_to_kg_s,
        )

        thrust = self.t_main_stovl_sl_n
        if thrust is None or thrust <= 0:
            return ExhaustPlumeParams()

        if self.exhaust_mdot_kg_s is not None:
            mdot = self.exhaust_mdot_kg_s
        elif self.id == 'AV-8B':
            mdot = lb_s_to_kg_s(PEGASUS_AIRFLOW_LB_S)
        else:
            mdot = EXHAUST_MDOT_KG_S

        u0 = calc_exhaust_u0_from_thrust_mdot(thrust, mdot)
        d0 = self.exhaust_d0_m
        if d0 is None and self.id == 'AV-8B':
            d0 = calc_exhaust_d0_from_engine_diameter(1.219)
        if d0 is None:
            d0 = EXHAUST_D0_M
        height = self.exhaust_height_m if self.exhaust_height_m is not None else self.wing_height_m
        if height is None:
            height = EXHAUST_HEIGHT_M
        return ExhaustPlumeParams(
            mdot_kg_s=mdot,
            u0_mps=u0,
            d0_m=d0,
            height_m=height,
        )

    @property
    def is_fighter(self) -> bool:
        """是否为战斗机角色。"""
        return self.aircraft_role.lower() == 'fighter'

    @property
    def is_bomber(self) -> bool:
        """是否为轰炸机角色。"""
        return self.aircraft_role.lower() == 'bomber'

    @property
    def combat_payload_mass_kg(self) -> float:
        """战斗/轰炸作战构型的有效载荷质量：轰炸机按最大载弹量。"""
        if self.is_bomber:
            return self.max_payload_kg
        return A2A_MISSILE_COUNT * self.missile_mass_kg

    @property
    def a2a_mass_kg(self) -> float:
        """正常起飞重量：空重 + 满内油 + 飞行员×0.1 t + 战斗/轰炸有效载荷。"""
        return (self.empty_kg + self.internal_fuel_kg
                + self.combat_payload_mass_kg
                + self.n_pilots * PILOT_LOAD_KG)


@dataclass(frozen=True)
class CarrierSpec:
    id: str
    name: str
    nation: str
    max_speed_kt: float
    ski_jump: bool
    total_deck_length_m: float
    ski_jump_angle_deg: float = 0.0
    ski_jump_height_m: float | None = None
    f35b_capable: bool = False
    notes: str = ''
    deck_length_source: str = ''

    def deck_wind_kt(self) -> float:
        return self.max_speed_kt

    def ski_jump_geom(self):
        if not self.ski_jump:
            return None
        return compute_ski_jump_arc(self.ski_jump_angle_deg, lip_height_m=self.ski_jump_height_m)

    def ski_jump_arc_m(self) -> float:
        g = self.ski_jump_geom()
        return g.arc_length_m if g else 0.0

    def ski_jump_horizontal_m(self) -> float:
        g = self.ski_jump_geom()
        return g.horizontal_m if g else 0.0

    def deck_fits_distance(self, required_m: float) -> bool:
        return required_m <= self.total_deck_length_m

py_sources.utils/missile_interception/missile_inter:
"""饱和打击仿真的公开资料预设（反舰弹 / 预警机 / 舰载雷达 / 防空弹）。

型号列表以导弹库与雷达库 CSV 为数据源：
  data/missile_interception_missile_database.csv（asm / sam）
  data/missile_interception_radar_database.csv（aew / ship）
前端经 build_all → data.json 的 missile_interception_presets 自动同步。
"""
from __future__ import annotations

from pathlib import Path
from typing import Any

from utils.database_csv import load_missile_interception_presets_csv
from utils.paths import MISSILE_INTERCEPTION_MISSILE_CSV, MISSILE_INTERCEPTION_RADAR_CSV


def load_presets(
    missile_path: str | Path | None = None,
    radar_path: str | Path | None = None,
) -> dict[str, list[dict[str, Any]]]:
    """从导弹库 + 雷达库加载四类预设；任一文件不存在时返回空分组（如 Pyodide 环境）。"""
    m_path = Path(missile_path) if missile_path is not None else MISSILE_INTERCEPTION_MISSILE_CSV
    r_path = Path(radar_path) if radar_path is not None else MISSILE_INTERCEPTION_RADAR_CSV
    if not m_path.is_file() or not r_path.is_file():
        return {'asm': [], 'aew': [], 'ship': [], 'sam': []}
    return load_missile_interception_presets_csv(m_path, r_path)


def get_preset_by_id(presets: list[dict[str, Any]], preset_id: str) -> dict[str, Any] | None:
    """按 id 查找预设；找不到返回 None。"""
    for item in presets:
        if item['id'] == preset_id:
            return item
    return None


def nations_sorted(presets: list[dict[str, Any]]) -> list[str]:
    """从预设列表提取去重国别并稳定排序（按首次出现顺序）。"""
    seen: list[str] = []
    for item in presets:
        nation = (item.get('nation') or '').strip()
        if nation and nation not in seen:
            seen.append(nation)
    return seen


def filter_presets_by_nation(
    presets: list[dict[str, Any]], nation: str
) -> list[dict[str, Any]]:
    """按国别过滤预设；国别为空时返回全部。"""
    key = (nation or '').strip()
    if not key:
        return list(presets)
    return [x for x in presets if (x.get('nation') or '').strip() == key]


def nations_union(*preset_lists: list[dict[str, Any]]) -> list[str]:
    """合并多组预设的国别，按各组内首次出现顺序去重（驱护+防空共用国别列表）。"""
    seen: list[str] = []
    for presets in preset_lists:
        for nation in nations_sorted(presets):
            if nation not in seen:
                seen.append(nation)
    return seen


def build_missile_interception_presets_payload(
    missile_path: str | Path | None = None,
    radar_path: str | Path | None = None,
) -> dict[str, list[dict[str, Any]]]:
    """构建前端/小程序/iOS 共用的饱和打击预设目录（源自双 CSV）。"""
    data = load_presets(missile_path, radar_path)
    return {
        'asm': list(data['asm']),
        'aew': list(data['aew']),
        'ship': list(data['ship']),
        'sam': list(data['sam']),
    }


# 兼容旧导入名：模块加载时从 CSV 填充（CLI/测试）
