            'stations': list(self.stations),
        }


def _opt_float(value: Any, default: float = 0.0) -> float:
    """解析浮点；空值用默认。"""
    if value is None or value == '':
        return default
    return float(value)


def load_munitions(path: str | Path | None = None) -> dict[str, dict[str, Any]]:
    """读取弹药库，返回 id → 记录。

    默认路径会再合并各碎片挂载目录中的弹药，供交互挂点下拉使用。
    """
    global _MUNITIONS_CACHE
    src = Path(path) if path is not None else MUNITIONS_CSV
    if path is None and _MUNITIONS_CACHE is not None:
        return _MUNITIONS_CACHE
    out: dict[str, dict[str, Any]] = {}
    with src.open(encoding='utf-8-sig', newline='') as fh:
        for row in csv.DictReader(fh):
            mid = (row.get('id') or '').strip()
            if not mid:
                continue
            dry = _opt_float(row.get('dry_mass_kg'), _opt_float(row.get('mass_kg')))
            fuel = _opt_float(row.get('fuel_kg'))
            mass = _opt_float(row.get('mass_kg'), dry + fuel)
            out[mid] = {
                'id': mid,
                'name': (row.get('name') or mid).strip(),
                'category': (row.get('category') or '').strip(),
                'mass_kg': mass,
                'dry_mass_kg': dry,
                'fuel_kg': fuel,
                'length_m': _opt_float(row.get('length_m')),
                'diameter_m': _opt_float(row.get('diameter_m')),
                'notes': (row.get('notes') or '').strip(),
            }
    if path is None:
        out = _maybe_merge_munitions(out)
        _MUNITIONS_CACHE = out
    return out


def load_aircraft_stations(path: str | Path | None = None) -> dict[str, Any]:
    """读取机型挂点库（含 version 与 aircraft 映射）。

    默认路径会合并碎片挂点模型（MiG-29K、F-16、阵风等），不覆盖 JSON 主库机型。
    Pyodide 若缺碎片模块则保留主库；此时应由前端 inject 完整 catalog。
    """
    global _STATIONS_CACHE
    src = Path(path) if path is not None else AIRCRAFT_STATIONS_JSON
    if path is None and _STATIONS_CACHE is not None:
        return _STATIONS_CACHE
    data = json.loads(src.read_text(encoding='utf-8'))
    if path is None:
        data = _maybe_merge_stations(data)
        _STATIONS_CACHE = data
    return data


def _maybe_merge_munitions(base: dict[str, dict[str, Any]]) -> dict[str, dict[str, Any]]:
    """合并碎片弹药；环境缺依赖时回退主库。"""
    try:
        from utils.combat_radius.loadout_unify import merge_munitions
        return merge_munitions(base)
    except (ImportError, ModuleNotFoundError, FileNotFoundError, OSError):
        return base


def _maybe_merge_stations(base: dict[str, Any]) -> dict[str, Any]:
    """合并碎片挂点；环境缺依赖时回退主库。"""
    try:
        from utils.combat_radius.loadout_unify import merge_aircraft_stations
        return merge_aircraft_stations(base)
    except (ImportError, ModuleNotFoundError, FileNotFoundError, OSError):
        return base


def inject_loadout_catalog(
    munitions: dict[str, dict[str, Any]] | None = None,
    stations: dict[str, Any] | None = None,
) -> None:
    """供 Pyodide/测试注入挂载目录，避免读盘。"""
    global _MUNITIONS_CACHE, _STATIONS_CACHE
    if munitions is not None:
        _MUNITIONS_CACHE = munitions
    if stations is not None:
        _STATIONS_CACHE = stations


def inject_loadout_catalog_payload(catalog: dict[str, Any] | None) -> None:
    """把前端 loadout_catalog 还原为 munitions/stations 缓存（Pyodide 用）。"""
    if not catalog:
        return
    munitions: dict[str, dict[str, Any]] = {}
    for row in catalog.get('munitions') or []:
        mid = str(row.get('id') or '').strip()
        if not mid:
            continue
        munitions[mid] = {
            'id': mid,
            'name': str(row.get('name') or mid),
            'category': str(row.get('category') or ''),
            'mass_kg': _opt_float(row.get('mass_kg')),
            'dry_mass_kg': _opt_float(row.get('dry_mass_kg'), _opt_float(row.get('mass_kg'))),
            'fuel_kg': _opt_float(row.get('fuel_kg')),
            'length_m': _opt_float(row.get('length_m')),
            'diameter_m': _opt_float(row.get('diameter_m')),
            'notes': str(row.get('notes') or ''),
        }
    aircraft_out: dict[str, Any] = {}
    for aid, ac in (catalog.get('aircraft') or {}).items():
        stations = []
        for st in ac.get('stations') or []:
            options = []
            for opt in st.get('options') or []:
                mid = str(opt.get('munition_id') or '').strip()
                if not mid:
                    continue
                options.append({
                    'munition_id': mid,
                    'qty': _opt_float(opt.get('qty'), 1.0),
                    **({'label': opt['label']} if opt.get('label') else {}),
                })
            stations.append({
                'id': st['id'],
                'label': st.get('label') or st['id'],
                'mount_style': st.get('mount_style') or 'wing_pylon',
                'options': options,
            })
        default_sel: dict[str, Any] = {}
        for sid, key in (ac.get('default_selection') or {}).items():
            mid, qty = _parse_selection_value(key)
            if mid:
                default_sel[str(sid)] = {'munition_id': mid, 'qty': qty}
        aircraft_out[str(aid)] = {
            'id': str(aid),
            'name': ac.get('name') or aid,
            'default_selection': default_sel,
            'stations': stations,
        }
    inject_loadout_catalog(
        munitions=munitions,
        stations={'version': int(catalog.get('version') or 1), 'aircraft': aircraft_out},
    )


def clear_loadout_caches() -> None:
    """清空挂载缓存。"""
    global _MUNITIONS_CACHE, _STATIONS_CACHE
    _MUNITIONS_CACHE = None
    _STATIONS_CACHE = None


def get_aircraft_station_def(aircraft_id: str) -> dict[str, Any] | None:
    """按机型 id 取挂点定义；无挂点表时返回 None。"""
    if not aircraft_id:
        return None
    root = load_aircraft_stations()
    aircraft = root.get('aircraft') or {}
    item = aircraft.get(aircraft_id)
    return dict(item) if isinstance(item, dict) else None


def option_key(munition_id: str, qty: float) -> str:
    """挂载选项稳定键：munition_id@qty。"""
    q = int(qty) if float(qty) == int(float(qty)) else float(qty)
    return f'{munition_id}@{q}'


def option_label(munition: dict[str, Any], qty: float, custom: str | None = None) -> str:
    """生成选项显示名。"""
    if custom:
        return custom
    name = munition.get('name') or munition.get('id') or '?'
    q = float(qty)
    if q <= 1:
        return str(name)
    if q == int(q):
        return f'{name} ×{int(q)}'
    return f'{name} ×{q}'


def expand_station_options(station: dict[str, Any], munitions: dict[str, dict[str, Any]]) -> list[dict[str, Any]]:
    """展开挂点选项（含空挂），供前端下拉。"""
    rows: list[dict[str, Any]] = [{
        'key': '',
        'munition_id': '',
        'qty': 0,
        'label': '空挂',
    }]
    for opt in station.get('options') or []:
        mid = str(opt.get('munition_id') or '').strip()
        if not mid:
            continue
        mun = munitions.get(mid)
        if mun is None:
            raise ValueError(f'挂点 {station.get("id")} 引用未知弹药 {mid}')
        qty = _opt_float(opt.get('qty'), 1.0)
        if qty <= 0:
            continue
        custom = opt.get('label')
        rows.append({
            'key': option_key(mid, qty),
            'munition_id': mid,
            'qty': qty,
            'label': option_label(mun, qty, str(custom) if custom else None),
            'mass_kg': mun['dry_mass_kg'] * qty + mun['fuel_kg'] * qty,
            'dry_mass_kg': mun['dry_mass_kg'] * qty,
            'fuel_kg': mun['fuel_kg'] * qty,
        })
    return rows


def build_loadout_catalog_payload() -> dict[str, Any]:
    """前端 catalog：弹药表 + 各机挂点与展开选项。"""
    munitions = load_munitions()
    root = load_aircraft_stations()
    aircraft_out: dict[str, Any] = {}
    for aid, raw in (root.get('aircraft') or {}).items():
        stations = []
        for st in raw.get('stations') or []:
            stations.append({
                'id': st['id'],
                'label': st.get('label') or st['id'],
                'mount_style': st.get('mount_style') or 'wing_pylon',
                'options': expand_station_options(st, munitions),
            })
        default_sel = {}
        for sid, sel in (raw.get('default_selection') or {}).items():
            mid = str(sel.get('munition_id') or '').strip()
            qty = _opt_float(sel.get('qty'), 1.0)
            if mid:
                default_sel[sid] = option_key(mid, qty)
        aircraft_out[aid] = {
            'id': aid,
            'name': raw.get('name') or aid,
            'stations': stations,
            'default_selection': default_sel,
        }
    return {
        'version': int(root.get('version') or 1),
        'munitions': list(munitions.values()),
        'aircraft': aircraft_out,
    }


def _aero_for_mount_style(mount_style: str, qty: float) -> dict[str, float]:
    """按挂点类型与枚数给出外挂气动参数。"""
    style = mount_style if mount_style in MOUNT_STYLE_AERO else 'wing_pylon'
    base = dict(MOUNT_STYLE_AERO[style])
    extra = max(float(qty) - 1.0, 0.0)
    base['interf'] = float(base['interf']) * (1.0 + MULTI_STORE_INTERF_PER_EXTRA * extra)
    return base


def resolve_loadout(
    aircraft_id: str,
    selection: dict[str, Any] | None,
) -> LoadoutSummary:
    """将各站选择解析为质量、外油与 StoreSpec 列表。

    selection: station_id → 选项键（munition@qty）或 {munition_id, qty}；空/缺省=空挂。
    """
    ac_def = get_aircraft_station_def(aircraft_id)
    if ac_def is None:
        raise ValueError(f'机型 {aircraft_id} 无挂点挂载表')
    munitions = load_munitions()
    sel = selection or {}
    summary = LoadoutSummary(aircraft_id=aircraft_id)
    station_by_id = {st['id']: st for st in (ac_def.get('stations') or [])}

    for st in ac_def.get('stations') or []:
        sid = st['id']
        raw = sel.get(sid)
        mid, qty = _parse_selection_value(raw)
        if not mid or qty <= 0:
            summary.stations.append({
                'station_id': sid,
                'label': st.get('label') or sid,
                'munition_id': '',
                'qty': 0,
                'label_option': '空挂',
            })
            continue
        allowed = {
            option_key(str(o.get('munition_id')), _opt_float(o.get('qty'), 1.0))
            for o in (st.get('options') or [])
        }
        key = option_key(mid, qty)
        if key not in allowed:
            raise ValueError(f'挂点 {sid} 不允许挂载 {key}')
        mun = munitions.get(mid)
        if mun is None:
            raise ValueError(f'未知弹药 {mid}')
        dry = float(mun['dry_mass_kg']) * qty
        fuel = float(mun['fuel_kg']) * qty
        if float(mun['fuel_kg']) > 0:
            summary.tank_dry_mass_kg += dry
            summary.external_fuel_kg += fuel
        else:
            summary.weapons_mass_kg += dry
        aero = _aero_for_mount_style(str(st.get('mount_style') or 'wing_pylon'), qty)
        mount_style = str(st.get('mount_style') or 'wing_pylon')
        # StoreSpec.mount 只认 internal/semi_recessed/pylon
        mount_kind = 'semi_recessed' if mount_style == 'semi_recessed' else 'pylon'
        summary.store_specs.append(StoreSpec(
            length_m=float(mun['length_m']),
            diameter_m=float(mun['diameter_m']),
            count=float(qty),
            mount=mount_kind,
            pylon_wetted_m2=float(aero['pylon_wetted_m2']),
            pylon_front_m2=float(aero['pylon_front_m2']),
            exposed_frac=float(aero['exposed_frac']),
            interf=float(aero['interf']),
            front_frac=float(aero['front_frac']),
            station_id=sid,
            munition_id=mid,
        ))
        custom = None
        for o in st.get('options') or []:
            if (
                str(o.get('munition_id')) == mid
                and abs(_opt_float(o.get('qty'), 1.0) - qty) < 1e-9
            ):
                custom = o.get('label')
                break
        summary.stations.append({
            'station_id': sid,
            'label': st.get('label') or sid,
            'munition_id': mid,
            'qty': qty,
            'label_option': option_label(mun, qty, str(custom) if custom else None),
            'dry_mass_kg': dry,
            'fuel_kg': fuel,
        })
    # 校验 selection 里没有未知站
    for sid in sel:
        if sid not in station_by_id and sel[sid] not in (None, '', {}):
            raise ValueError(f'未知挂点 {sid}')
    return summary


def _parse_selection_value(raw: Any) -> tuple[str, float]:
    """解析单站选择：空 / 键 / 字典。"""
    if raw is None or raw == '' or raw == {}:
        return '', 0.0
    if isinstance(raw, dict):
        mid = str(raw.get('munition_id') or '').strip()
        qty = _opt_float(raw.get('qty'), 1.0 if mid else 0.0)
        return mid, qty
    text = str(raw).strip()
    if not text or text == 'empty':
        return '', 0.0
    if '@' in text:
        mid, _, q = text.partition('@')
        return mid.strip(), _opt_float(q, 1.0)
    return text, 1.0


def apply_loadout_to_params(params: dict[str, Any]) -> dict[str, Any]:
    """若请求含 loadout，则覆盖挂载质量、总油量与 target.store_specs。"""
    loadout = params.get('loadout')
    if not loadout:
        return params
    if isinstance(loadout, str):
        loadout = json.loads(loadout)
    if not isinstance(loadout, dict):
        raise ValueError('loadout 必须为对象')
    aircraft_id = str(
        loadout.get('aircraft_id')
        or params.get('aircraft_id')
        or ''
    ).strip()
    if not aircraft_id:
        raise ValueError('loadout 缺少 aircraft_id')
    selection = loadout.get('selection')
    if selection is None:
        # 允许 loadout 直接是 station→选项 映射
        selection = {
            k: v for k, v in loadout.items()
            if k not in ('aircraft_id', 'selection')
        }
    summary = resolve_loadout(aircraft_id, selection)
    out = dict(params)
    out['aircraft_id'] = aircraft_id
    base_fuel = _opt_float(out.get('internal_fuel_kg'))
    out['internal_fuel_kg'] = base_fuel + summary.external_fuel_kg
    # 空战重量：挂载干重按「一件」计入，兼容 n_missiles×missile_mass
    out['missile_mass_kg'] = summary.payload_mass_kg
    out['n_missiles'] = 1.0 if summary.payload_mass_kg > 0 else 0.0
    target = dict(out.get('target') or {})
    target['store_specs'] = [asdict(s) for s in summary.store_specs]
    target['n_stores'] = summary.n_store_units
    target['store_mount'] = 'pylon' if summary.store_specs else target.get('store_mount', 'pylon')
    out['target'] = target
    out['loadout_summary'] = summary.to_dict()
    return out

py_sources.utils/combat_radius/flight_profile.py:
"""作战半径任务剖面：高-高-高、高-低-高、低-低-低。

剖面影响任务油量开销（爬升额外 / 降落节省）以及布雷盖半径的巡航段组合。
"""
from __future__ import annotations

from typing import Any

from utils.combat_radius.breguet import combat_radius_m, mixed_combat_radius_m
from utils.combat_radius.combat_radius_config import load_combat_radius_config
from utils.combat_radius.cruise_search import (
    ALT_COARSE_M,
    ALT_MAX_M,
    ALT_MIN_M,
    ALT_REFINE_M,
    CruiseContext,
    search_best_altitude,
)

# 低-低-低 / 高-低-高 的低空段搜索带（m）
LOW_ALT_MIN_M = 300.0
LOW_ALT_MAX_M = 3000.0
LOW_ALT_COARSE_M = 500.0
LOW_ALT_REFINE_M = 100.0

# 高-低-高 低空段默认用 Ma 0.8（超音速低空通常不可飞）
HI_LO_HI_LOW_MACH = 0.8

DEFAULT_PROFILE_ID = 'hi_hi_hi'
PROFILE_IDS = ('hi_hi_hi', 'hi_lo_hi', 'lo_lo_lo')

_BUILTIN_PROFILES: dict[str, dict[str, Any]] = {
    'hi_hi_hi': {
        'label': '高-高-高',
        'mode': 'symmetric_high',
        'climb_extra_km': 120.0,
        'descent_save_km': 87.5,
        'note': '进出与巡航均在高空；爬升/降落开销按标准 120 / 87.5 km 等价油耗入账。',
    },
    'hi_lo_hi': {
        'label': '高-低-高',
        'mode': 'mixed_high_low',
        'climb_extra_km': 180.0,
        'descent_save_km': 50.0,
        'note': '高空进出、目标区低空渗透；额外爬升/下降按 180 / 50 km 等价油耗入账；半径按高空去程 + 低空回程闭合。',
    },
    'lo_lo_lo': {
        'label': '低-低-低',
        'mode': 'symmetric_low',
        'climb_extra_km': 30.0,
        'descent_save_km': 25.0,
        'note': '全程低空贴地/掠海；爬升/降落开销按 30 / 25 km 等价油耗入账；半径在 0.3–3 km 带搜索最佳巡航。',
    },
}


def _profiles_from_config() -> dict[str, dict[str, Any]]:
    """合并 JSON 配置与内置默认值。"""
    cfg = load_combat_radius_config().get('flight_profiles') or {}
    raw = cfg.get('profiles') or {}
    merged: dict[str, dict[str, Any]] = {}
    for pid in PROFILE_IDS:
        base = dict(_BUILTIN_PROFILES[pid])
        override = raw.get(pid) or {}
        base.update({k: v for k, v in override.items() if v is not None})
        base['id'] = pid
        merged[pid] = base
    return merged


def default_flight_profile_id() -> str:
    """默认剖面 id（缺省高-高-高）。"""
    cfg = load_combat_radius_config().get('flight_profiles') or {}
    raw = str(cfg.get('default') or DEFAULT_PROFILE_ID).strip()
    return raw if raw in PROFILE_IDS else DEFAULT_PROFILE_ID


def resolve_flight_profile(profile_id: str | None) -> dict[str, Any]:
    """解析剖面 id，非法值回退默认。"""
    pid = str(profile_id or '').strip() or default_flight_profile_id()
    profiles = _profiles_from_config()
    if pid not in profiles:
        pid = default_flight_profile_id()
    return dict(profiles[pid])


def flight_profile_options() -> list[dict[str, Any]]:
    """前端/小程序/iOS 共用的剖面列表（固定顺序）。"""
    profiles = _profiles_from_config()
    return [
        {
            'id': pid,
            'label': profiles[pid]['label'],
            'note': profiles[pid].get('note'),
        }
        for pid in PROFILE_IDS
    ]


def profile_mission_fuel_km(profile_id: str | None) -> tuple[float, float]:
    """返回 (climb_extra_km, descent_save_km)。"""
    prof = resolve_flight_profile(profile_id)
    return float(prof['climb_extra_km']), float(prof['descent_save_km'])


def search_low_altitude_point(
    ctx: CruiseContext,
    mach: float,
    alt_min_m: float = LOW_ALT_MIN_M,
    alt_max_m: float = LOW_ALT_MAX_M,
    coarse_m: float = LOW_ALT_COARSE_M,
    refine_m: float = LOW_ALT_REFINE_M,
) -> Any | None:
    """在低空带搜索最佳巡航点（L/D×η_o 最大且满足推力裕度）。"""
    if mach <= 0:
        raise ValueError('马赫数须为正')
    return search_best_altitude(ctx, mach, alt_min_m, alt_max_m, coarse_m, refine_m)


def _scored_usable(scored: Any) -> bool:
    """评分点是否可用于布雷盖。"""
    return (
        scored is not None
        and scored.tsfc_kg_n_s is not None
        and scored.v0 > 0
        and scored.ld > 0
        and scored.eta_o > 0
    )


def profile_combat_radius_m(
    profile: dict[str, Any],
    high_scored: Any,
    *,
    mach: float,
    mass_initial_kg: float,
    mass_final_kg: float,
    ctx: CruiseContext | None = None,
    low_scored: Any | None = None,
    alt_min_m: float = ALT_MIN_M,
    alt_max_m: float = ALT_MAX_M,
    coarse_m: float = ALT_COARSE_M,
    refine_m: float = ALT_REFINE_M,
) -> float:
    """按剖面模式由评分点估算作战半径（米）。"""
    mode = str(profile.get('mode') or 'symmetric_high')
    if mode == 'symmetric_high':
        if not _scored_usable(high_scored):
            raise ValueError('高空巡航点不可用')
        return combat_radius_m(
            high_scored.v0,
            high_scored.tsfc_kg_n_s,
            high_scored.ld,
            mass_initial_kg,
            mass_final_kg,
        )
    if ctx is None:
        raise ValueError('该剖面需要巡航搜索上下文')
    if mode == 'symmetric_low':
        low = low_scored
        if low is None:
            low = search_low_altitude_point(ctx, mach)
        if not _scored_usable(low):
            raise ValueError('低空巡航点不可用')
        return combat_radius_m(
            low.v0,
            low.tsfc_kg_n_s,
            low.ld,
            mass_initial_kg,
            mass_final_kg,
        )
    if mode == 'mixed_high_low':
        if not _scored_usable(high_scored):
            raise ValueError('高空去程点不可用')
        low = low_scored
        if low is None:
            low_mach = mach if mach <= 1.0 else HI_LO_HI_LOW_MACH
            low = search_low_altitude_point(ctx, low_mach)
        if not _scored_usable(low):
            raise ValueError('低空回程点不可用')
        return mixed_combat_radius_m(
            high_scored.v0,
            high_scored.tsfc_kg_n_s,
            high_scored.ld,
            low.v0,
            low.tsfc_kg_n_s,
            low.ld,
            mass_initial_kg,
            mass_final_kg,
        )
    raise ValueError(f'未知剖面模式: {mode}')

py_sources.utils/combat_radius/combat_radius_preset:
"""作战半径机型几何预设（源自统一机型库 data/aircraft_database.csv）。

前端经 build_all → data.json 的 combat_radius_presets 自动同步。
"""
from __future__ import annotations

from pathlib import Path
from typing import Any

from utils.combat_radius.lift_drag import Aircraft, aircraft_from_dict, aircraft_to_dict
from utils.database_csv import load_combat_radius_aircraft_csv, load_combat_radius_engine_csv
from utils.paths import COMBAT_RADIUS_AIRCRAFT_CSV, COMBAT_RADIUS_ENGINE_CSV

_INJECTED_AIRCRAFT: list[dict[str, Any]] | None = None
_INJECTED_ENGINES: list[dict[str, Any]] | None = None


def inject_combat_radius_presets(
    aircraft: list[dict[str, Any]] | None = None,
    engines: list[dict[str, Any]] | None = None,
) -> None:
    """注入机型/发动机预设（Pyodide / 测试用）；优先于 CSV。"""
    global _INJECTED_AIRCRAFT, _INJECTED_ENGINES
    if aircraft is not None:
        _INJECTED_AIRCRAFT = [dict(item) for item in aircraft]
    if engines is not None:
        _INJECTED_ENGINES = [dict(item) for item in engines]


def clear_injected_combat_radius_presets() -> None:
    """清除注入的预设，恢复从 CSV 加载。"""
    global _INJECTED_AIRCRAFT, _INJECTED_ENGINES
    _INJECTED_AIRCRAFT = None
    _INJECTED_ENGINES = None


def load_presets(path: str | Path | None = None) -> list[dict[str, Any]]:
    """加载机型几何预设；注入优先于默认 CSV；显式路径仍读文件。"""
    if path is None and _INJECTED_AIRCRAFT is not None:
        return [dict(item) for item in _INJECTED_AIRCRAFT]
    csv_path = Path(path) if path is not None else COMBAT_RADIUS_AIRCRAFT_CSV
    if not csv_path.is_file():
        return []
    return load_combat_radius_aircraft_csv(csv_path)


def get_preset_by_id(presets: list[dict[str, Any]], preset_id: str) -> dict[str, Any] | None:
    """按 id 查找预设；找不到返回 None。"""
    for item in presets:
        if item['id'] == preset_id:
            return item
    return None


def _preset_sort_key(item: dict[str, Any]) -> tuple[str, str, str]:
    """选择器排序键：国别 → 名称 → id（大小写不敏感）。"""
    return (
        (item.get('nation') or '').strip().casefold(),
        (item.get('name') or '').strip().casefold(),
        (item.get('id') or '').strip().casefold(),
    )


def sort_presets_by_nation_then_name(
    presets: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    """按国别再按名称字母序排列机型预设（不修改入参）。"""
    return sorted(presets, key=_preset_sort_key)


def preset_select_label(preset: dict[str, Any]) -> str:
    """选择器显示名：有国别时为「国别 · 名称」。"""
    nation = (preset.get('nation') or '').strip()
    name = (preset.get('name') or '').strip()
    if nation:
        return f'{nation} · {name}'
    return name


def selected_aircraft_name(
    preset: dict[str, Any] | None,
    fallback: str = '未命名',
) -> str:
    """机型显示名取自预设；选择器已展示机型，表单不再另开名称栏。"""
    if not preset:
        return fallback
    name = str(preset.get('name') or '').strip()
    return name or fallback


def preset_to_aircraft_dict(preset: dict[str, Any]) -> dict[str, Any]:
    """预设记录 → Aircraft 字段字典（去掉 id/nation/ld_known/notes）。"""
    ac = aircraft_from_dict(preset)
    return aircraft_to_dict(ac)


def preset_to_aircraft(preset: dict[str, Any]) -> Aircraft:
    """预设记录 → Aircraft。"""
    return aircraft_from_dict(preset)


def build_combat_radius_presets_payload(path: str | Path | None = None) -> list[dict[str, Any]]:
    """构建前端/小程序/iOS 共用的作战半径机型预设列表（按国别再按名称排序）。"""
    return sort_presets_by_nation_then_name(load_presets(path))


def load_engine_presets(path: str | Path | None = None) -> list[dict[str, Any]]:
    """加载发动机预设；注入优先于默认 CSV；显式路径仍读文件。"""
    if path is None and _INJECTED_ENGINES is not None:
        return [dict(item) for item in _INJECTED_ENGINES]
    csv_path = Path(path) if path is not None else COMBAT_RADIUS_ENGINE_CSV
    if not csv_path.is_file():
        return []
    return load_combat_radius_engine_csv(csv_path)


def build_combat_radius_engine_presets_payload(path: str | Path | None = None) -> list[dict[str, Any]]:
    """构建前端/小程序/iOS 共用的发动机预设列表。"""
    return list(load_engine_presets(path))

py_sources.simulators/missile_range/missile_range.p:
"""导弹射程仿真入口：按弹种估算单发，并按同一推进剂假设刷新样本表。"""
from __future__ import annotations

from typing import Any

from utils.missile_range.classes import estimate_by_class, glide_shape
from utils.missile_range.dataset import (
    all_missile_cases,
    build_missile_range_catalog_payload,
    evaluate_dataset,
)
from utils.missile_range.estimate import (
    DEFAULT_ISP_S,
    DEFAULT_PROPELLANT_DENSITY,
    optimize_hgv_geometry,
)


def opt_float(value: Any, default: float) -> float:
    """解析可选浮点；空值使用默认。"""
    if value is None or value == '':
        return default
    return float(value)


def opt_optional_float(value: Any) -> float | None:
    """空值表示不覆盖；有值则转成浮点。"""
    if value is None or value == '':
        return None
    return float(value)


def opt_bool(value: Any, default: bool) -> bool:
    """解析可选布尔。字符串按常见开关词处理。"""
    if value is None or value == '':
        return default
    if isinstance(value, str):
        return value.strip().lower() not in {'', '0', 'false', 'no', 'off'}
    return bool(value)


def resolve_ballistic_single_stage(params: dict[str, Any]) -> bool:
    """普通弹道是否锁定单级。

    ballistic_single_stage 优先。旧字段 ballistic_two_stage 为假时同样锁定单级。
    """
    if 'ballistic_single_stage' in params and params.get('ballistic_single_stage') not in (None, ''):
        return opt_bool(params.get('ballistic_single_stage'), False)
    if 'ballistic_two_stage' in params and params.get('ballistic_two_stage') not in (None, ''):
        return not opt_bool(params.get('ballistic_two_stage'), True)
    return False


def _required_float(params: dict[str, Any], key: str) -> float:
    if key not in params or params[key] is None or params[key] == '':
        raise ValueError(f'缺少参数 {key}')
    return float(params[key])


def include_dataset_rows(params: dict[str, Any]) -> bool:
    """单发估算是否附带重算整张样本表。

    缺省仍返回样本表，供小程序和已有调用方使用。
    网页在固体比冲和密度都没变时传 include_rows=false，只算当前这一发。
    """
    return opt_bool(params.get('include_rows'), True)


def run_estimate_from_params(params: dict[str, Any] | None) -> dict[str, Any]:
    """按表单参数估算一发。固体比冲重算预设表；吸气比冲只作用于当前这一发。"""
    params = params or {}
    try:
        isp = opt_float(params.get('isp_s'), DEFAULT_ISP_S)
        density = opt_float(params.get('propellant_density'), DEFAULT_PROPELLANT_DENSITY)
        ballistic_single_stage = resolve_ballistic_single_stage(params)
        opt_geom_raw = params.get('optimize_geometry', True)
        if isinstance(opt_geom_raw, str):
            optimize_geometry = opt_geom_raw.strip().lower() in {'1', 'true', 'yes', 'on'}
        else:
            optimize_geometry = bool(opt_geom_raw)
        result = estimate_by_class(
            missile_class=str(params.get('missile_class') or 'hgv_biconic'),
            length_m=_required_float(params, 'length_m'),
            diameter_m=_required_float(params, 'diameter_m'),
            warhead_mass_kg=_required_float(params, 'warhead_kg'),
            v_launch_mach=opt_float(params.get('v_launch_mach'), 0.85),
            h_launch_km=opt_float(params.get('h_launch_km'), 13.0),
            isp_s=isp,
            propellant_density=density,
            isp_air_s=opt_optional_float(params.get('isp_air_s')),
            ballistic_single_stage=ballistic_single_stage,
            optimize_geometry=optimize_geometry,
            l_head_m=opt_optional_float(params.get('l_head_m')),
            d_head_m=opt_optional_float(params.get('d_head_m')),
        )
        payload: dict[str, Any] = {'success': True, 'result': result}
        if include_dataset_rows(params):
            payload['rows'] = evaluate_dataset(isp_s=isp, propellant_density=density)
        return payload
    except (TypeError, ValueError) as exc:
        return {'success': False, 'error': str(exc)}


def run_optimize_geometry_from_params(params: dict[str, Any] | None) -> dict[str, Any]:
    """搜索包含战斗部与制控组件的滑翔体最优长度与直径（使总射程最大）。"""
    params = params or {}
    try:
        missile_class = str(params.get('missile_class') or 'hgv_biconic')
        shape = glide_shape(missile_class)
        if shape is None:
            raise ValueError(f'弹种 {missile_class} 不是助推滑翔弹，无法进行滑翔体几何寻优')
        length_m = _required_float(params, 'length_m')
        diameter_m = _required_float(params, 'diameter_m')
        warhead_kg = _required_float(params, 'warhead_kg')
        v_mach = opt_float(params.get('v_launch_mach'), 0.85)
        h_km = opt_float(params.get('h_launch_km'), 13.0)
        isp = opt_float(params.get('isp_s'), DEFAULT_ISP_S)
        density = opt_float(params.get('propellant_density'), DEFAULT_PROPELLANT_DENSITY)
        min_fineness = opt_optional_float(params.get('min_fineness'))
        min_d_head = opt_optional_float(params.get('min_d_head_m'))
        max_d_head = opt_optional_float(params.get('max_d_head_m'))
        opt = optimize_hgv_geometry(
            length_m=length_m,
            diameter_m=diameter_m,
            warhead_mass_kg=warhead_kg,
            hgv_type=shape,
            v_launch_mach=v_mach,
            h_launch_km=h_km,
            isp_s=isp,
            propellant_density=density,
            min_fineness=min_fineness,
            min_d_head_m=min_d_head,
            max_d_head_m=max_d_head,
        )
        return {'success': True, 'optimization': opt, 'result': opt['result']}
    except (TypeError, ValueError) as exc:
        return {'success': False, 'error': str(exc)}


def run_dataset_from_params(params: dict[str, Any] | None) -> dict[str, Any]:
    """只重算预设样本表。"""
    params = params or {}
    try:
        rows = evaluate_dataset(
            isp_s=opt_float(params.get('isp_s'), DEFAULT_ISP_S),
            propellant_density=opt_float(params.get('propellant_density'), DEFAULT_PROPELLANT_DENSITY),
        )
    except (TypeError, ValueError) as exc:
        return {'success': False, 'error': str(exc)}
    return {'success': True, 'rows': rows, 'count': len(all_missile_cases())}


def run_presets_from_params(params: dict[str, Any] | None = None) -> dict[str, Any]:
    """返回目录中的弹种、默认值和默认推进剂下的样本表。"""
    del params
    payload = build_missile_range_catalog_payload()
    return {'success': True, **payload}

