        return {'success': False, 'error': f'未知 action: {action}'}
    try:
        return handler(params or {})
    except Exception as exc:
        return {'success': False, 'error': str(exc)}


def run_missile_range_json(payload: dict[str, Any] | str) -> dict[str, Any]:
